def entry(n,part,pages,task,proof,steps,scenes,checks,rule,hint,caption,*,title=None,refs=None):
    c=lesson(n,part,pages[0],task,proof,steps,scenes,checks,rule,hint,caption,
             None if title else 'Дай ответ и обоснуй его с помощью соответствующих сторон, углов или признака равенства.',
             title=title,refs=refs)
    c['source'].update(chapter='XV',printedPages=pages,pdfPages=[x+1 for x in pages])
    c['review']['reviewer']=f'Атанасян и др., Геометрия 7–9, 14-е переработанное издание, 2023, гл. XV, печатные с. {pages[0]}–{pages[-1]} (с. {pages[0]+1}–{pages[-1]+1} выданного PDF). Проверены исходные номера, подпункты и чертежи.'
    return c


def pair(title,vertices,matches,other,*,fan=False,marks=()):
    originals=list(vertices)
    new=list(matches)
    pts={**dict(zip(originals,vertices.values(),strict=True)),**dict(zip(new,other,strict=True))}
    sides=[(group[i],group[(i+1)%len(group)]) for group in (originals,new) for i in range(len(group))]
    lines=[(pts[group[0]],pts[group[i]]) for group in (originals,new) for i in range(2,len(group)-1)] if fan else []
    return diagram(title,pts,sides,[*lines,*marks])


def scaled(title,points,kx,ky,phi=0,fan=False):
    cs,sn=cos(radians(phi)),sin(radians(phi));new=[]
    for x,y in points.values():new.append((kx*x*cs-ky*y*sn,kx*x*sn+ky*y*cs))
    shift=max(x for x,y in points.values())-min(x for x,y in new)+1.7
    return pair(title,points,[n+'′' for n in points],[(x+shift,y) for x,y in new],fan=fan)


