def hexes(title,scale):
    pts={'A':(0,0),'B':(.9,1.2),'C':(2.9,1.2),'D':(4.1,0),'E':(1.7,-1.25),'F':(.65,-1.2)}
    pts={k:(x*scale,y*scale) for k,(x,y) in pts.items()}
    right=[(x+.5*scale,-y-3.9*scale) for x,y in pts.values()]
    marks=[]
    for polygon in (list(pts.values()),right):
        for i,count in ((0,3),(2,1),(3,2)):
            x,y=polygon[i];a=polygon[i-1];b=polygon[(i+1)%6]
            start=atan2(a[1]-y,a[0]-x);end=atan2(b[1]-y,b[0]-x)
            change=(end-start+pi)%(2*pi)-pi
            for ring in range(count):
                r=(.24+.09*ring)*scale
                curve=[(x+r*cos(start+change*j/9),y+r*sin(start+change*j/9)) for j in range(10)]
                marks.extend(zip(curve,curve[1:]))
    return pair(title,pts,list('GHKLMN'),right,marks=marks)


